    /// <summary>
    /// The health potions (item group 14): apple, small, normal and large healing potion, the complex potions and the
    /// elite healing potions.
    /// </summary>
    private static readonly short[] HealthPotions = [0, 1, 2, 3, 38, 39, 40, 70, 94];

    /// <summary>
    /// The mana potions (item group 14): small, normal and large mana potion and the elite mana potion.
    /// </summary>
    private static readonly short[] ManaPotions = [4, 5, 6, 71];

    private readonly IContext _context;

    private readonly GameConfiguration _gameConfiguration;

    /// <summary>
    /// Initializes a new instance of the <see cref="Season21LabyrinthRoomsInitializer"/> class.
    /// </summary>
    /// <param name="context">The context.</param>
    /// <param name="gameConfiguration">The game configuration.</param>
    public Season21LabyrinthRoomsInitializer(IContext context, GameConfiguration gameConfiguration)
    {
        this._context = context;
        this._gameConfiguration = gameConfiguration;
    }

    /// <summary>
    /// Creates the configuration of the data: 38 areas, 11 missions, 30 paths and the goblin (757, 20 %, 2000 points,
    /// while fewer than 10 rooms are open).
    /// </summary>
    /// <returns>The configuration.</returns>
    public static LabyrinthRoomsConfiguration CreateConfiguration() => new()
    {
        Areas = [.. Areas.Select(a => new LabyrinthArea { Number = a.Number, MapNumber = a.Map, StartX = a.StartX, StartY = a.StartY, EndX = a.EndX, EndY = a.EndY })],
        Missions =
        [
            .. Missions.Select(m => new LabyrinthMission
            {
                Type = (LabyrinthAreaType)m.Type,
                Index = m.Index,
                Goals = [.. m.Goals.Select(g => new LabyrinthGoal { Kind = (LabyrinthGoalKind)g.Kind, Target = g.Target })],
                Monsters = [.. m.Monsters.Select(n => new LabyrinthMonster { MonsterNumber = n.Number, Count = n.Count })],
            }),
        ],
        Paths = [.. Paths.Select((rooms, i) => new LabyrinthPath { Number = i + 1, Rooms = rooms })],
        Goblin = new EventBonusMonster { MonsterNumber = 757, Count = 1, ChancePercent = 20, Points = 2000 },
        GoblinMaximumOpenRooms = 10,
        HealthPotions = [.. HealthPotions],
        ManaPotions = [.. ManaPotions],
    };

    /// <summary>
    /// Applies the rooms; a configuration the operator already has stays, and so does the switch after the first run.
    /// </summary>
    public void Initialize()
    {
        var configuration = Season21PlugInConfigurations.GetOrCreate<LabyrinthRoomsConfiguration>(this._context, this._gameConfiguration, typeof(LabyrinthRoomsPlugIn).GUID, out var plugIn);
        if (configuration is null || configuration.Paths.Count > 0)
        {
            return;
        }

        // The first application turns the feature on; later ones leave the operator's switch alone.
        plugIn.IsActive = true;
        plugIn.SetConfiguration(CreateConfiguration(), null);
    }
}
